<?php require '../includes/layout.php'; require_role(['admin']); $d=db();$from=$_GET['from']??date('Y-m-d',strtotime('-6 days'));$to=$_GET['to']??date('Y-m-d');$fromOk=preg_match('/^\d{4}-\d{2}-\d{2}$/',$from);$toOk=preg_match('/^\d{4}-\d{2}-\d{2}$/',$to);if(!$fromOk)$from=date('Y-m-d',strtotime('-6 days'));if(!$toOk)$to=date('Y-m-d');$where="o.created_at>=? AND o.created_at<? AND o.status<>'cancelled'";$params=[$from,$to.' 23:59:59'];
$summary=$d->prepare("SELECT COUNT(*) orders,COALESCE(SUM(o.total),0) sales,COALESCE(SUM(o.tax),0) tax,COALESCE(SUM(o.service_charge),0) service FROM orders o WHERE $where");$summary->execute($params);$summary=$summary->fetch();
$best=$d->prepare("SELECT i.product_name,SUM(i.qty) qty,SUM(i.qty*i.price) revenue FROM order_items i JOIN orders o ON o.id=i.order_id WHERE $where GROUP BY i.product_name ORDER BY qty DESC LIMIT 10");$best->execute($params);$best=$best->fetchAll();
if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="galleta-sales-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Sales report',$from,$to]);fputcsv($out,['Orders',$summary['orders']]);fputcsv($out,['Sales',$summary['sales']]);fputcsv($out,[]);fputcsv($out,['Product','Quantity','Revenue']);foreach($best as $row)fputcsv($out,[$row['product_name'],$row['qty'],$row['revenue']]);fclose($out);exit;}
head('Reports');?><div class="flex flex-wrap items-end justify-between gap-3 mb-4"><div><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Performance</p><h1 class="text-2xl font-semibold mt-1">Sales reports</h1></div><a class="rounded-full border border-line px-4 py-2 text-sm hover:bg-soft" href="?from=<?=e($from)?>&to=<?=e($to)?>&format=csv">Export CSV</a></div>
<form method="get" class="<?=card('p-4 mb-5')?> flex flex-wrap items-end gap-3"><label class="text-sm">From<input class="<?=INP?> mt-1" type="date" name="from" value="<?=e($from)?>"></label><label class="text-sm">To<input class="<?=INP?> mt-1" type="date" name="to" value="<?=e($to)?>"></label><button class="<?=BTN?>">Apply dates</button></form>
<div class="grid grid-cols-2 gap-3 sm:grid-cols-4 mb-5"><div class="<?=card('p-4')?>"><div class="text-xs text-mute">Orders</div><b class="text-2xl"><?=$summary['orders']?></b></div><div class="<?=card('p-4')?>"><div class="text-xs text-mute">Sales</div><b class="text-2xl"><?=money($summary['sales'])?></b></div><div class="<?=card('p-4')?>"><div class="text-xs text-mute">Tax</div><b class="text-2xl"><?=money($summary['tax'])?></b></div><div class="<?=card('p-4')?>"><div class="text-xs text-mute">Service</div><b class="text-2xl"><?=money($summary['service'])?></b></div></div>
<div class="<?=card('overflow-x-auto')?>"><h2 class="p-4 font-medium">Best-selling products</h2><table class="w-full min-w-[30rem] text-sm"><thead><tr class="border-t border-line text-left text-xs uppercase tracking-wide text-mute"><th class="p-3">Product</th><th>Quantity</th><th class="p-3 text-right">Revenue</th></tr></thead><tbody><?php foreach($best as $row):?><tr class="border-t border-line"><td class="p-3"><?=e($row['product_name'])?></td><td><?=$row['qty']?></td><td class="p-3 text-right"><?=money($row['revenue'])?></td></tr><?php endforeach?></tbody></table></div><?php foot();
